function Bullets([string[]]$items){ ($items | ForEach-Object { "- $_" }) -join "`n" }
function Diagram($m){ "```mermaid`nflowchart LR`n  UI[Consumidor] --> API[API $($m.code)]`n  API --> CORE[Controladores/Servicios]`n  CORE --> DB[(Datos)]`n  CORE --> DEP[Dependencias]`n```" }

$map = @('# MODULOS DETECTADOS DEL SISTEMA SPI','','| MODULO | DESCRIPCION | ARCHIVOS RELACIONADOS | DEPENDENCIAS |','|---|---|---|---|')
foreach($m in $modules){ $map += "| $($m.name) | $($m.desc) | $($m.files -join '; ') | $($m.deps -join '; ') |" }
Set-Content -Path (Join-Path $base 'modulos_detectados.md') -Value ($map -join "`n")

$rtm = @('# MATRIZ DE TRAZABILIDAD DEL SISTEMA SPI','','| URS-ID | FRS-ID | ARCHIVO | FUNCION |','|---|---|---|---|')

foreach($m in $modules){
  $urs = Join-Path $base ("URS/URS_modulo_{0}.md" -f $m.slug)
  $frs = Join-Path $base ("FRS/FRS_modulo_{0}.md" -f $m.slug)
  $ds  = Join-Path $base ("DS/DS_modulo_{0}.md" -f $m.slug)
  $reqLines = Bullets ($m.reqs | ForEach-Object { "$($_.id): $($_.text)" })
  $frsBlocks = foreach($r in $m.reqs){ "### FRS-$($r.id.Substring(4))`n**Descripcion:** $($r.text)`n`n**Entradas:** $($r.input)`n`n**Proceso:** $($r.process)`n`n**Salida:** $($r.output)`n`n**Componente:** $($r.file) -> $($r.fn)" }
  $ursText = "# URS - $($m.name)`n`n## 1. Introduccion`nDocumento de requerimientos de usuario reconstruido por ingenieria inversa del codigo actual.`n`n## 2. Proposito`nDefinir lo que el modulo debe hacer desde la perspectiva del usuario y del negocio.`n`n## 3. Alcance`n$(Bullets $m.funcs)`n`n## 4. Actores del sistema`n$(Bullets $m.actors)`n`n## 5. Descripcion general del modulo`n$($m.desc)`n`n## 6. Funcionalidades identificadas`n$(Bullets $m.funcs)`n`n## 7. Requerimientos funcionales`n$reqLines`n`n## 8. Requerimientos no funcionales`n$(Bullets $m.nfr)`n`n## 9. Reglas de negocio`n$(Bullets $m.rules)`n`n## 10. Dependencias`n$(Bullets $m.deps)`n"
  $frsText = "# FRS - $($m.name)`n`n## 1. Introduccion`nEspecificacion funcional derivada del URS y alineada a la implementacion real.`n`n## 2. Logica funcional del modulo`n$(Bullets $m.funcs)`n`n## 3. Especificaciones funcionales`n$($frsBlocks -join "`n`n")`n`n## 4. Endpoints principales`n$(Bullets $m.eps)`n`n## 5. Validaciones y observaciones`n$(Bullets $m.rules)`n"
  $dsText = "# DS - $($m.name)`n`n## 1. Arquitectura del modulo`nModulo expuesto por API REST y consumido por frontend o procesos internos del SPI.`n`n## 2. Componentes`n$(Bullets $m.files)`n`n## 3. Modelos de datos y entidades`n$(Bullets $m.data)`n`n## 4. Flujos internos`n$(Bullets $m.funcs)`n`n## 5. Dependencias tecnicas`n$(Bullets $m.deps)`n`n## 6. Endpoints principales`n$(Bullets $m.eps)`n`n## 7. Diagrama tecnico`n$(Diagram $m)`n"
  Set-Content -Path $urs -Value $ursText
  Set-Content -Path $frs -Value $frsText
  Set-Content -Path $ds -Value $dsText
  foreach($r in $m.reqs){ $rtm += "| $($r.id) | FRS-$($r.id.Substring(4)) | $($r.file) | $($r.fn) |" }
}

Set-Content -Path (Join-Path $base 'RTM/RTM_sistema_spi.md') -Value ($rtm -join "`n")
$idx = @('# INFORME FINAL DE VALIDACION DEL SISTEMA SPI','','## 1. Lista de modulos','- Ver [modulos_detectados.md](./modulos_detectados.md).','','## 2. Documentos URS')
$idx += ($modules | ForEach-Object { "- [URS_modulo_$($_.slug).md](./URS/URS_modulo_$($_.slug).md)" })
$idx += @('','## 3. Documentos FRS')
$idx += ($modules | ForEach-Object { "- [FRS_modulo_$($_.slug).md](./FRS/FRS_modulo_$($_.slug).md)" })
$idx += @('','## 4. Documentos DS')
$idx += ($modules | ForEach-Object { "- [DS_modulo_$($_.slug).md](./DS/DS_modulo_$($_.slug).md)" })
$idx += @('','## 5. Matriz de trazabilidad','- [RTM_sistema_spi.md](./RTM/RTM_sistema_spi.md)','', '## 6. Observaciones','- Los modulos transversales `security`, `approvals`, `gmail`, `calendar`, `management` e `integrations` se integraron dentro de los modulos funcionales donde efectivamente operan en el codigo.','- Cuando la implementacion no permitio cerrar completamente la regla de negocio, se debe considerar requiere validacion funcional.')
Set-Content -Path (Join-Path $base 'informe_final.md') -Value ($idx -join "`n")
